#!/usr/bin/env node
/**
 * Concatenate the browser-half fragments into the single `client.js` module the
 * Harness ModuleLoader evaluates. Run: node paper-lab/build.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const pkg = JSON.parse(fs.readFileSync(path.join(here, 'package.json'), 'utf8'))
const parts = ['01-style.js', '02-math.js', '03-data.js', '03b-scene.js', '04-ui.js', '04b-scene-ui.js', '05-panel.js']
let body = ''
for (const part of parts) {
  const text = fs.readFileSync(path.join(here, 'src', part), 'utf8')
  body += `\n/* ===================== ${part} ===================== */\n` + text + '\n'
}

const three = fs.readFileSync(path.join(here, 'vendor', 'three.min.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '')
// Force the UMD build onto window.THREE even when the host evaluates client.js
// in a CommonJS-ish scope that defines module/exports.
const threeGlobal = `(function(module, exports, define){\n${three}\n}).call(window, undefined, undefined, undefined);
if (window && !window.THREE && typeof globalThis !== 'undefined' && globalThis.THREE) window.THREE = globalThis.THREE`

const out = `/* Generated by build.mjs — edit src/*.js, then rebuild. */
/* Three.js r128 (MIT) — vendored for the 3D layer scene. */
${threeGlobal}
window.__ModuleLoader__.load({
  id: ${JSON.stringify(pkg.name)},
  factory(require) {
    const React = require('react')
    const THREE = window.THREE
    const h = React.createElement
    const { useState, useEffect, useMemo, useRef, useCallback } = React
${body}
  },
})
`

fs.writeFileSync(path.join(here, 'client.js'), out)
console.log('client.js', (Buffer.byteLength(out) / 1024).toFixed(1) + ' KB')
